<script setup>
import VideoEmbed from '../components/VideoEmbed.vue'
import { formatDate } from "../utils/workflow.js"
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { apiGet, apiRequest } from '../services/api.js'
import { label } from '../utils.js'
const contents = ref([]), campaigns = ref([]), error = ref(''), notice = ref(''), busy = ref(false), filter = ref('all')
const media = url => /\.(mp4|webm)(\?|$)/i.test(url)
async function load() { contents.value = await apiGet('/me/contents'); campaigns.value = await apiGet('/me/campaigns') }
async function complete(c) { busy.value = true; error.value = ''; try { await apiRequest(`/me/contents/${c.id}/complete`, 'POST'); await load(); notice.value = 'Conclusão registrada somente no seu espaço. Continue no seu ritmo.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function stage(c, stage) { busy.value = true; error.value = ''; try { await apiRequest(`/me/campaign-participations/${c.participant_id}`, 'PUT', { stage, version: Number(c.version) }); await load(); notice.value = stage === 'opted_out' ? 'Sua escolha foi registrada.' : 'Participação atualizada. Isso não substitui consultas ou retornos.' } catch (e) { error.value = e.message } finally { busy.value = false } }
onMounted(async () => { busy.value = true; try { await load() } catch (e) { error.value = e.message } finally { busy.value = false } })
onBeforeUnmount(()=>{if('speechSynthesis' in window)speechSynthesis.cancel()})
function readAloud(text){if(!('speechSynthesis' in window)){error.value='Leitura por voz indisponível neste navegador. Consulte a transcrição ou peça apoio à equipe.';return}speechSynthesis.cancel();const speech=new SpeechSynthesisUtterance(text);speech.lang='pt-BR';speech.rate=0.9;speechSynthesis.speak(speech)}
</script>
<template><p class="eyebrow">MEU CUIDADO · UM PASSO DE CADA VEZ</p><h1>Você também merece espaço na sua rotina</h1><p class="lead">Conteúdos rápidos para conhecer a plataforma e continuar seu acompanhamento na APS. Se algo dificultar seu retorno, peça apoio à equipe.</p><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><p v-if="busy">Carregando…</p><RouterLink to="/find-care" class="btn btn-success mb-4">Ver meu próximo passo no cuidado →</RouterLink><section class="mb-5"><h2 class="h4">Campanhas e ciclos para você</h2><p v-if="!campaigns.length">Nenhum ciclo aberto para seu vínculo neste momento.</p><div class="row g-3"><div v-for="c in campaigns" :key="c.id" class="col-md-6"><article class="card card-body h-100"><p class="eyebrow">{{ c.cycle_label }}</p><h3 class="h5">{{ c.title }}</h3><p>{{ c.objective }}</p><p class="small text-secondary">Até {{ formatDate(c.end_date) }} · {{ label(c.stage) }}</p><div class="d-flex flex-wrap gap-2"><button class="btn btn-outline-success" :disabled="busy" @click="stage(c, 'interested')">Quero participar</button><button class="btn btn-success" :disabled="busy || c.stage === 'completed'" @click="stage(c, 'completed')">Concluí os conteúdos do ciclo</button><button class="btn btn-link text-secondary" :disabled="busy" @click="stage(c, 'opted_out')">Não participar agora</button></div><p class="small text-secondary mt-3 mb-0">Concluir conteúdos é uma declaração sua; não significa que uma meta clínica foi atingida.</p></article></div></div></section><section><div class="d-flex flex-wrap justify-content-between gap-3 mb-3"><h2 class="h4">Conteúdos rápidos</h2><label>Mostrar <select v-model="filter" class="form-select"><option value="all">Todos</option><option value="platform">Como usar a plataforma</option><option value="aps">Continuidade da APS</option></select></label></div><p v-if="!contents.length">A equipe está preparando os conteúdos. Vídeos só aparecem após publicação e revisão.</p><div class="row g-4"><div v-for="c in contents.filter(c => filter === 'all' || c.category === filter)" :key="c.id" class="col-md-6 col-xl-4"><article class="card card-body h-100"><span class="badge text-bg-light align-self-start mb-3">{{ c.category === 'platform' ? 'Usando a plataforma' : 'Continuidade da APS' }} · {{ Math.ceil(c.duration_seconds / 60) }} min</span><h3 class="h5">{{ c.title }}</h3><p>{{ c.summary }}</p><VideoEmbed v-if="c.video_url" :url="c.video_url" :title="c.title"/><button v-else type="button" class="btn btn-outline-success mb-3" @click="readAloud(c.transcript)">▶ Ouvir orientação</button><details class="mb-3"><summary>Texto / transcrição acessível</summary><p class="mt-3" style="white-space: pre-wrap">{{ c.transcript }}</p></details><button class="btn mt-auto" :class="c.completed_at ? 'btn-outline-secondary' : 'btn-success'" :disabled="busy || !!c.completed_at" @click="complete(c)">{{ c.completed_at ? 'Concluído por você' : 'Concluí este conteúdo' }}</button></article></div></div></section></template>
